import{_ as n,c as a,o as t,a3 as p}from"./chunks/framework.C5U8cnJv.js";const b=JSON.parse('{"title":"包管理工具","description":"","frontmatter":{},"headers":[],"relativePath":"nodejs/包管理工具.md","filePath":"nodejs/包管理工具.md"}'),s={name:"nodejs/包管理工具.md"},e=p(`<h1 id="包管理工具" tabindex="-1">包管理工具 <a class="header-anchor" href="#包管理工具" aria-label="Permalink to &quot;包管理工具&quot;">​</a></h1><p>前端开发最常用：npm、cnpm、yarn、pnpm</p><h2 id="npm" tabindex="-1">npm <a class="header-anchor" href="#npm" aria-label="Permalink to &quot;npm&quot;">​</a></h2><p>Node.js 的默认包管理器</p><p>版本锁定文件：package-lock.json</p><blockquote><p>npm v12 默认不自动执行<strong>依赖包内</strong>的 preinstall / install / postinstall / prepare 脚本；当前项目自身的生命周期脚本仍然会执行</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>简单来说，以后执行：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>npm install</span></span>
<span class="line"><span></span></span>
<span class="line"><span>默认不会再自动运行依赖中的：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>preinstall</span></span>
<span class="line"><span>install</span></span>
<span class="line"><span>postinstall</span></span>
<span class="line"><span>prepare</span></span>
<span class="line"><span></span></span>
<span class="line"><span>等脚本</span></span></code></pre></div><h2 id="cnpm" tabindex="-1">cnpm <a class="header-anchor" href="#cnpm" aria-label="Permalink to &quot;cnpm&quot;">​</a></h2><p>是淘宝镜像的命令行工具，用于加速安装依赖包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g cnpm --registry=https://registry.npmmirror.com</span></span></code></pre></div><h2 id="yarn" tabindex="-1">yarn <a class="header-anchor" href="#yarn" aria-label="Permalink to &quot;yarn&quot;">​</a></h2><p>Meta（原 Facebook）开源的包管理器。</p><p>版本锁定文件：<code>yarn.lock</code>;</p><p>配置文件： <code>yarnrc.yml</code>;</p><blockquote><p>yarn v4 默认不自动执行<strong>依赖包内</strong>的 postinstall 等生命周期脚本；当前项目/工作区自身的生命周期脚本仍然会执行</p></blockquote><h2 id="pnpm" tabindex="-1">pnpm <a class="header-anchor" href="#pnpm" aria-label="Permalink to &quot;pnpm&quot;">​</a></h2><p>基于内容寻址存储，结合硬链接+符号链接，复用包文件，节省磁盘空间、安装速度快；默认非扁平化 node_modules 结构，天然阻断幽灵依赖，代码里不能导入未在 package.json 声明的依赖（如果打开 <code>shamefully-hoist=true</code> ，pnpm 会把一部分依赖提升到顶层，就和 npm/yarn 扁平模式一样，幽灵依赖又能正常导入了）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g pnpm</span></span></code></pre></div><p>版本锁定文件：pnpm-lock.yaml</p><blockquote><p>pnpm v10 默认<strong>不自动执行依赖包内</strong>的 preinstall / install / postinstall 等生命周期脚本；当前项目自身的生命周期脚本仍然会执行。</p></blockquote><p><a href="https://pnpm.io/zh/pnpm-cli" target="_blank" rel="noreferrer">https://pnpm.io/zh/pnpm-cli</a></p><h2 id="npmrc" tabindex="-1">.npmrc <a class="header-anchor" href="#npmrc" aria-label="Permalink to &quot;.npmrc&quot;">​</a></h2><p>npm、pnpm 会读取项目 <code>.npmrc</code>, cnpm 仅识别少量字段</p><table tabindex="0"><thead><tr><th>配置项</th><th>作用</th><th>支持工具</th></tr></thead><tbody><tr><td>registry</td><td>设置包源地址</td><td>npm / pnpm / cnpm</td></tr><tr><td>proxy / https-proxy</td><td>网络代理</td><td>npm / pnpm / cnpm</td></tr><tr><td>strict-ssl</td><td>是否校验 SSL 证书</td><td>npm / pnpm</td></tr><tr><td>allow-scripts</td><td>npm 脚本白名单（v12+）：默认拦截第三方依赖生命周期脚本，仅名单内的包允许执行脚本，项目自身脚本不受限制</td><td>npm</td></tr><tr><td>ignore-scripts</td><td>全局禁用所有生命周期脚本（包含依赖包以及项目自身脚本）</td><td>npm / pnpm</td></tr><tr><td>allow-builds[]</td><td>pnpm 编译脚本白名单（v10+）：默认拦截第三方依赖生命周期脚本，仅名单内的包允许执行构建脚本，项目自身脚本不受限制</td><td>pnpm</td></tr><tr><td>shamefully-hoist</td><td>开启扁平化 node_modules，允许幽灵依赖，丢失 pnpm 依赖校验优势</td><td>pnpm</td></tr><tr><td>save-exact</td><td>保存精确版本号，版本号不带 ^ 符号</td><td>npm / pnpm</td></tr><tr><td>_authToken</td><td>私有源登录令牌，不要提交到 Git 仓库</td><td>npm / pnpm</td></tr></tbody></table><h2 id="npx" tabindex="-1">npx <a class="header-anchor" href="#npx" aria-label="Permalink to &quot;npx&quot;">​</a></h2><p>npm 5.2.0 版本之后内置的命令行工具。</p><p>可以直接执行包的命令，<strong>不需要提前全局安装</strong>：既可以运行项目 node_modules 内已安装的包命令，也能自动临时下载远程包执行，执行完毕后自动清理。</p><blockquote><p>备注：npm v7+ 中 <code>npx</code> 是 <code>npm exec</code> 的别名；加上 <code>--no-install</code> 参数时，只会调用本地已安装的包命令，找不到就报错，不会自动下载远程包。</p></blockquote><blockquote><p>npx 只能执行包在 <code>package.json</code> 的 <code>bin</code> 字段声明的可执行命令（安装后放在 <code>node_modules/.bin</code>），<strong>不能直接执行 package.json 中 scripts 脚本</strong>。</p></blockquote>`,29),o=[e];function d(l,r,c,i,m,h){return t(),a("div",null,o)}const g=n(s,[["render",d]]);export{b as __pageData,g as default};
